INSERT INTO customers VALUES('4e32c2a5-11e6-551c-d8eb-b96a8cfb9497','KH004958','Chú Dương','0866032087','block B -12.98 Chung cư Bộ Công An','',NULL,NULL,'le',0.0,'2019-03-29T15:21:45.253+00:00',0.0,NULL,'','true',0.0,NULL,NULL,NULL,NULL,'','ca_nhan',NULL,NULL,replace('Quạt lắp ok rồi em nhé. Khi nào cần lắp thêm a ll\nTrần 2m6\n03/10/2021 Quạt tự tăng giảm số, đã ktra 1 lần tháng 6/2021 rồi vẫn bị tình trạng này tiếp tục, KT qua xem và xử lý giúp E nhé\n\n22/10/2021 Khách mua 2Sky đèn t4/2021, tháng 5 và tháng 7 đã thay 2 bộ đk cho 2c, nhưng vẫn bị tự tắt quạt, tự chạy chậm. Khách nói cả 2 cây ko bị thường xuyên, lâu lâu bị tự nhảy số, nhất vào ban đêm, tối anh bật số 3 ngủ quạt tự chạy nhanh số 6. \nEm đã báo khách nếu vẫn bị vậy thì khả năng mang 2 động cơ + 2 bộ remote về hãng để ktra\nKT qua xem giúp em có thể xử lí đc ko, ko thì tháo về test ạ\n24/10/2021 "Thứ 7 Cường có qua thay 2 động cơ + bộ đk mới. Hiện 1 chiếc đã ổn chưa có dấu hiệu gì\n1 Chiếc đang quay bật/tắt đèn là dừng luôn quạt. KT xem xử lý giúp em cho dứt điểm được không ạ ?\nKhách bảo cái tay cầm của chiếc bị đấy lắc lắc nó kêu lộc cộc bên trong nên ko biết phải do tay cầm đấy ko. \n25/10 Giang ktra\n5/11 Đức thay tay cầm\nKhách yêu cầu Giang qua xử lý vì trc h Giang đều lắp cho nhà khách\n9/7/2022 Giang qa thay 1 tín hiệu cho khách, vẫn lỗi cũ và hư tín hiệu','\n',char(10)),NULL,NULL,0.0);
