INSERT INTO customers VALUES('8af0ad71-4af1-5fb7-47bb-3af07ed54c12','KH011353','Chị Phương','0936034479','101/5 Thành Thái','Phường 14',NULL,NULL,'le',0.0,'2022-04-17T19:41:28.257+00:00',0.0,NULL,'',NULL,0.0,NULL,NULL,NULL,NULL,'','ca_nhan',NULL,NULL,replace('[24/05/2024 11:41:04] Kim Kim Quạt Mrvu: Dạ em chào chị ạ . \nEm là Kim bên Quạt Trần Mr.Vũ . Năm 2022 nhà mình có mua Quạt Trần bên em  hiện tại đã  đến hạn bảo trì , kiểm tra vệ sinh để đảm bảo an toàn khi vận hàng rồi đó ạ. \nTheo khuyến cáo của nhà sản xuất, Quạt phải được kiểm tra định kỳ sau 6 tháng sử dụng để đảm bảo hoạt động an toàn và tốt nhất ạ . \nVì sử dụng 1 thời gian dài quạt có thể bị bụi bẩn, trờn ren, lỏng ốc... Quạt sử dụng  1 thời gian dài có thể bị bụi bẩn, trờn ren.... \nChị liên hệ em để đặt lịch bên em qua spa vệ sinh kiểm tra  sớm nhất cho mình nhé ạ\n[24/05/2024 11:47:34] Cao Lan Phuong: Đợt quạt nhà c bị hư bóng đèn liên hệ bạn bên e qua hỗ trợ sửa, bên e nói bóng đèn hư thì c tự sửa ah\n[24/05/2024 11:51:58] Kim Kim Quạt Mrvu: Dạ chị , vì mẫu quạt nhà chị đang dùng chỉ là dạng bóng đuôi E14 bình thường thôi . Nên chị mua bóng về tự thay cũng dễ lắm ạ , nếu bên em qua thay cho chị sẽ có tính phí ạ , vì phần bòn đèn bên em  k có BH ạ\n[24/05/2024 11:58:17] Cao Lan Phuong: Đúng rồi c liên hệ thay tính tiền mà sẵn cùng bảo trì máy lun. Vậy mà bên em im lặng không trả lời lun \n[24/05/2024 12:00:12] Kim Kim Quạt Mrvu: dạ e xin lỗi c , này do sai xót bên em ạ , hiện quạt vẫn dùng bình thường phải không c ?\n[24/05/2024 12:02:09] Kim Kim Quạt Mrvu: dạ trước c làm việc với bạn nào ạ , Vì e mới tiếp nhận lại thông tin nên ko có nắm rõ ạ','\n',char(10)),NULL,NULL,0.0);
