PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE brands (
  id    TEXT NOT NULL PRIMARY KEY,
  name  TEXT NOT NULL
);
CREATE TABLE categories (
  id    TEXT NOT NULL PRIMARY KEY,
  name  TEXT NOT NULL
);
CREATE TABLE branches (
  id         TEXT NOT NULL PRIMARY KEY,
  name       TEXT NOT NULL,
  address    TEXT,
  phone      TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE work_difficulties (
  id          TEXT NOT NULL PRIMARY KEY,
  name        TEXT NOT NULL,
  description TEXT,
  bonus       REAL NOT NULL DEFAULT 0
);
CREATE TABLE work_types (
  id          TEXT NOT NULL PRIMARY KEY,
  name        TEXT NOT NULL,
  price       REAL NOT NULL DEFAULT 0,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  description TEXT
);
CREATE TABLE site_settings (
  key   TEXT NOT NULL PRIMARY KEY,
  value TEXT NOT NULL DEFAULT ''
);
CREATE TABLE cash_voucher_types (
  id   TEXT NOT NULL PRIMARY KEY,
  name TEXT NOT NULL,
  kind TEXT NOT NULL
);
CREATE TABLE products (
  id          TEXT NOT NULL PRIMARY KEY,
  sku         TEXT NOT NULL UNIQUE,
  name        TEXT NOT NULL,
  category_id TEXT,
  brand_id    TEXT,
  power       TEXT,
  color       TEXT,
  blade_size  TEXT,
  sale_price  REAL NOT NULL DEFAULT 0,
  cost_price  REAL NOT NULL DEFAULT 0,
  tech_fee    REAL NOT NULL DEFAULT 0,
  min_stock   INTEGER NOT NULL DEFAULT 0,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  description TEXT,
  image_url   TEXT,
  FOREIGN KEY (category_id) REFERENCES categories(id),
  FOREIGN KEY (brand_id)    REFERENCES brands(id)
);
CREATE TABLE users (
  id             TEXT NOT NULL PRIMARY KEY,
  username       TEXT NOT NULL UNIQUE,
  password       TEXT NOT NULL,
  full_name      TEXT NOT NULL,
  phone          TEXT,
  email          TEXT,
  role           TEXT NOT NULL DEFAULT 'cashier',
  is_admin       INTEGER NOT NULL DEFAULT 0,
  branch_ids     TEXT NOT NULL DEFAULT '[]',   -- JSON array (SQLite không có array type)
  permissions    TEXT NOT NULL DEFAULT '[]',   -- JSON array
  active         INTEGER NOT NULL DEFAULT 1,   -- boolean → 1/0
  kv_employee_id TEXT,
  created_at     TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE user_activity_logs (
  id         TEXT NOT NULL PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  user_id    TEXT,
  action     TEXT,
  metadata   TEXT,  -- JSON blob
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE employees (
  id         TEXT NOT NULL PRIMARY KEY,
  name       TEXT NOT NULL,
  phone      TEXT,
  role       TEXT NOT NULL DEFAULT 'Nhân viên',
  branch_id  TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (branch_id) REFERENCES branches(id)
);
CREATE TABLE customers (
  id               TEXT NOT NULL PRIMARY KEY,
  external_code    TEXT UNIQUE,
  name             TEXT NOT NULL,
  phone            TEXT,
  address          TEXT,
  ward             TEXT,
  district         TEXT,
  province         TEXT,
  group_name       TEXT NOT NULL DEFAULT 'le',
  debt             REAL NOT NULL DEFAULT 0,
  created_at       TEXT NOT NULL DEFAULT (datetime('now')),
  total_sales      REAL NOT NULL DEFAULT 0,
  type             TEXT,
  email            TEXT,
  gender           TEXT,
  total_buy        REAL DEFAULT 0,
  birthday         TEXT,   -- date → TEXT (ISO 8601)
  tax_code         TEXT,
  cccd             TEXT,
  passport_no      TEXT,
  company_name     TEXT,
  customer_type    TEXT DEFAULT 'ca_nhan',
  bank_name        TEXT,
  bank_account     TEXT,
  note             TEXT,
  created_by       TEXT,
  created_by_name  TEXT,
  debt_adjustment  REAL NOT NULL DEFAULT 0
);
CREATE TABLE orders (
  id             TEXT NOT NULL PRIMARY KEY,
  code           TEXT NOT NULL UNIQUE,
  customer_id    TEXT,
  branch_id      TEXT,
  employee_id    TEXT,
  status         TEXT NOT NULL DEFAULT 'draft',
  subtotal       REAL NOT NULL DEFAULT 0,
  discount       REAL NOT NULL DEFAULT 0,
  total          REAL NOT NULL DEFAULT 0,
  deposit        REAL NOT NULL DEFAULT 0,
  paid           REAL NOT NULL DEFAULT 0,
  note           TEXT,
  created_at     TEXT NOT NULL DEFAULT (datetime('now')),
  payment_method TEXT DEFAULT 'tien_mat',
  vat_rate       REAL DEFAULT 0,
  vat_amount     INTEGER DEFAULT 0,
  discount_type  TEXT DEFAULT 'amount',
  discount_pct   REAL DEFAULT 0,
  completed_at   TEXT,
  FOREIGN KEY (employee_id) REFERENCES users(id),
  FOREIGN KEY (customer_id) REFERENCES customers(id),
  FOREIGN KEY (branch_id)   REFERENCES branches(id)
);
CREATE TABLE order_items (
  id         TEXT NOT NULL PRIMARY KEY,
  order_id   TEXT NOT NULL,
  product_id TEXT,
  qty        INTEGER NOT NULL,
  unit_price REAL NOT NULL,
  discount   REAL NOT NULL DEFAULT 0,
  total      REAL NOT NULL,
  FOREIGN KEY (order_id)   REFERENCES orders(id),
  FOREIGN KEY (product_id) REFERENCES products(id)
);
CREATE TABLE stock (
  product_id TEXT NOT NULL,
  branch_id  TEXT NOT NULL,
  qty        INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (product_id, branch_id),
  FOREIGN KEY (product_id) REFERENCES products(id),
  FOREIGN KEY (branch_id)  REFERENCES branches(id)
);
CREATE TABLE stock_movements (
  id          TEXT NOT NULL PRIMARY KEY,
  type        TEXT NOT NULL,
  branch_id   TEXT,
  product_id  TEXT,
  qty         INTEGER NOT NULL,
  unit_cost   REAL DEFAULT 0,
  note        TEXT,
  ref_type    TEXT,
  ref_id      TEXT,
  created_by  TEXT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  from_branch TEXT,
  to_branch   TEXT,
  FOREIGN KEY (branch_id)  REFERENCES branches(id),
  FOREIGN KEY (product_id) REFERENCES products(id)
);
CREATE TABLE stock_transfer_items (
  id          TEXT NOT NULL PRIMARY KEY,
  transfer_id TEXT NOT NULL,
  product_id  TEXT,
  qty         INTEGER NOT NULL,
  FOREIGN KEY (transfer_id) REFERENCES stock_transfers(id),
  FOREIGN KEY (product_id)  REFERENCES products(id)
);
CREATE TABLE schedule_assignments (
  schedule_id TEXT NOT NULL,
  user_id     TEXT NOT NULL,
  PRIMARY KEY (schedule_id, user_id),
  FOREIGN KEY (schedule_id) REFERENCES schedules(id)
);
CREATE TABLE schedule_difficulties (
  schedule_id   TEXT NOT NULL,
  difficulty_id TEXT NOT NULL,
  qty           INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (schedule_id, difficulty_id),
  FOREIGN KEY (schedule_id)   REFERENCES schedules(id),
  FOREIGN KEY (difficulty_id) REFERENCES work_difficulties(id)
);
CREATE TABLE tech_fees (
  id          TEXT NOT NULL PRIMARY KEY,
  schedule_id TEXT NOT NULL,
  product_id  TEXT NOT NULL,
  qty         INTEGER NOT NULL DEFAULT 1,
  unit_fee    REAL NOT NULL DEFAULT 0,
  user_id     TEXT,
  FOREIGN KEY (user_id)     REFERENCES users(id),
  FOREIGN KEY (schedule_id) REFERENCES products(id),
  FOREIGN KEY (product_id)  REFERENCES products(id)
);
CREATE TABLE activity_logs (
  id          TEXT NOT NULL PRIMARY KEY,
  employee_id TEXT,
  action      TEXT NOT NULL,
  detail      TEXT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS "schedules" (
      "id" TEXT, "title" TEXT, "type" TEXT, "status" TEXT, "scheduled_date" TEXT, "scheduled_time" TEXT, "customer_id" TEXT, "branch_id" TEXT, "order_id" TEXT, "address" TEXT, "note" TEXT, "created_by" TEXT, "assigned_by" TEXT, "work_type_id" TEXT, "created_at" TEXT
    );
CREATE TABLE IF NOT EXISTS "stock_transfers" (
      "id" TEXT, "from_branch" TEXT, "to_branch" TEXT, "status" TEXT, "note" TEXT, "created_by" TEXT, "created_at" TEXT, "confirmed_at" TEXT
    );
CREATE TABLE IF NOT EXISTS "user_branches" (
      "user_id" TEXT, "branch_id" TEXT
    );
CREATE TABLE IF NOT EXISTS "user_permissions" (
      "user_id" TEXT, "permission" TEXT
    );
CREATE TABLE IF NOT EXISTS "cash_vouchers" (
      "id" TEXT, "code" TEXT, "type" TEXT, "fund_type" TEXT, "branch_id" TEXT, "amount" INTEGER, "voucher_type_id" TEXT, "payer_receiver" TEXT, "note" TEXT, "accounting" INTEGER, "status" TEXT, "created_by" TEXT, "created_at" TEXT, "collector_user_id" TEXT, "payer_customer_id" TEXT, "payer_user_id" TEXT, "receiver_customer_id" TEXT, "from_kind" TEXT, "from_id" TEXT, "from_name" TEXT, "to_kind" TEXT, "to_id" TEXT, "to_name" TEXT
    );
CREATE INDEX idx_products_category   ON products(category_id);
CREATE INDEX idx_products_brand      ON products(brand_id);
CREATE INDEX idx_orders_customer     ON orders(customer_id);
CREATE INDEX idx_orders_branch       ON orders(branch_id);
CREATE INDEX idx_orders_status       ON orders(status);
CREATE INDEX idx_orders_created_at   ON orders(created_at);
CREATE INDEX idx_order_items_order   ON order_items(order_id);
CREATE INDEX idx_order_items_product ON order_items(product_id);
CREATE INDEX idx_stock_branch        ON stock(branch_id);
CREATE INDEX idx_stock_movements_product  ON stock_movements(product_id);
CREATE INDEX idx_stock_movements_branch   ON stock_movements(branch_id);
CREATE INDEX idx_stock_movements_created  ON stock_movements(created_at);
CREATE INDEX idx_employees_branch    ON employees(branch_id);
CREATE INDEX idx_customers_phone     ON customers(phone);
CREATE INDEX idx_activity_logs_emp   ON activity_logs(employee_id);
CREATE INDEX idx_activity_logs_ts    ON activity_logs(created_at);
COMMIT;
